}

.message-author {
    font-weight: 600;
    font-size: 0.9rem;
    color: #fff;
}

.message-time {
    font-size: 0.72rem;
    color: #72767d;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    word-wrap: break-word;
}

.message-reactions {
